docker compose exec -T node sh -c 'cat > /tmp/t.js << "EOF"
const { JSDOM } = require("/tmp/node_modules/jsdom");
const fs = require("fs");
const quillSrc = fs.readFileSync("/app/public/admin/js/quill/quill.min.js","utf8");

function run(label, content){
  const dom = new JSDOM(`<!DOCTYPE html><body><div id="ed">${content}</div></body>`, {runScripts:"outside-only", pretendToBeVisual:true});
  const {window} = dom;
  global.window = window; global.document = window.document;
  window.eval(quillSrc);
  const Quill = window.Quill;
  // SmartBreak setup identical to input.js
  const Break = Quill.import("blots/break");
  const Embed = Quill.import("blots/embed");
  class SmartBreak extends Break { length(){return 1;} value(){return "\n";} insertInto(p,r){Embed.prototype.insertInto.call(this,p,r);} }
  SmartBreak.blotName="break"; SmartBreak.tagName="BR"; Quill.register(SmartBreak);
  try {
    const q = new Quill("#ed", { theme:"snow", modules:{ toolbar:[[{header:[2,3,false]}]] } });
    console.log(label, "OK ->", JSON.stringify(q.root.innerHTML).slice(0,120));
  } catch(e){
    console.log(label, "CRASH ->", e.message);
  }
}
run("h2", "<h2>contemporanea sopra</h2>");
run("p", "<p>wewee</p>");
run("span-br", "<p>a<span><br></span>b</p>");
EOF
